// TH18 v1.00a Stage 4 MainSub02 (st04.ecl 908-929) + GirlC01 (283-439).
// Source coordinates are used unchanged. Ranks 0..3 follow the source !E/!N/!H/!LO branches.
const TIME_LIMIT: int = 1800;
const OPENING_BUFFER: int = 120;

// Source GirlC01_at/at2 etEx type8 (ANGLE_ACCEL): a=120 frames, speed += r per frame,
// angle += 0.0052359877 rad/frame (0.3 deg), positive at / negative at2.
// The etEx type2 ANIM birth retreat (-4*initial speed) is folded into sh_dist below.
xformdef SPIN_P(accel: fx) {
    set_ang_vel(0.3deg);
    @120 set_accel(accel);
    set_ang_vel(0deg);
    set_accel(0fx);
}
xformdef SPIN_N(accel: fx) {
    set_ang_vel(-0.3deg);
    @120 set_accel(accel);
    set_ang_vel(0deg);
    set_accel(0fx);
}

// Source GirlC01_at S:340-377: et1 (called at) waits 30/15/15/10 before the first ring,
// then one RANDRAD base per volley; count/delta/EX accel/rounds/interval are rank-split.
async sub girl_at() {
    var rank: int = global(GVAR_RANK);
    var n: int = 15;
    var delta: angle = 30deg;
    var accel: fx = 0.008333fx;
    var rounds: int = 5;
    var interval: int = 60;
    var delay: int = 30;
    if rank == 1 { n = 25; delta = 30deg; rounds = 10; interval = 30; delay = 15; }
    if rank == 2 { n = 25; delta = 20deg; accel = 0.011667fx; rounds = 10; interval = 30; delay = 15; }
    if rank == 3 { n = 25; delta = 15deg; accel = 0.015fx; rounds = 15; interval = 20; delay = 10; }
    sh_reset(0);
    sh_sprite(0, TH18_RICE, 10);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, n, 1);
    sh_speed(0, 1.5fx, 0fx);
    // Source etDist(16) plus ANIM -4*1.5px, both along the bullet angle.
    sh_dist(0, 10fx);
    sh_xform(0, SPIN_P(accel));
    wait(delay);
    for i in 0..rounds {
        var base: angle = rand(65536) as angle; // %RANDRAD, one per volley
        sh_angle(0, base, 0deg);
        sh_fire(0);
        wait(interval);
    }
}

