// Source GirlC01 S:283-307: decelerate over 80 frames, then start both emitters,
// accelerate again, wait 300, then leave downward at 1.4.
async sub girl() {
    set_invuln(65535);              // training shell; source hurt/body geometry kept below
    set_hurtbox(16fx);              // source setHurtbox(32,32): native radius = width*0.5
    set_hitbox(12fx);               // source setHitbox(24,24): native radius = width*0.5
    move_vel(0, 90deg, 2fx, EASE_LINEAR);
    move_speed(80, 0fx, EASE_QUAD_IN);   // source moveVelTime mode1 (t^2)
    wait(80);
    spawn girl_at();                // source lines 297-298, same frame
    spawn girl_at2();
    move_speed(80, 0.2fx, EASE_QUAD_IN);
    wait(300);
    move_speed(80, 1.4fx, EASE_QUAD_IN);
    loop { wait(1000); }
}

// Source MainSub02 S:908-929: first GirlC01 at (0,-32), then 800 one-frame polls that
// replace the tracked enemy only while it is not alive; ±128 alternating x plus RANDF2*48.
// After the loop one fixed creation, then wait 400. No fixed kill count is introduced.
async sub wave() {
    wait(OPENING_BUFFER);
    var last: int = spawn_enemy(0fx, -32fx, 3200, 0, 0, 0, girl);
    var f0: fx = 128fx;
    var c: int = 800;
    while c > 0 {
        if enemy_alive(last) == 0 {
            var u: fx = rand(65536) as fx / 65536;
            last = spawn_enemy(f0 + u * 48fx, -32fx, 2000, 0, 0, 0, girl);
            f0 = -f0;
        }
        wait(1);
        c = c - 1;
    }
    var u2: fx = rand(65536) as fx / 65536;
    _ = spawn_enemy(f0 + u2 * 48fx, -32fx, 1800, 0, 0, 0, girl);
    wait(400);
    loop { wait(600); }
}

async sub encounter() {
    // Training-only phase owner at (0,0), no body collision; real enemies keep source geometry.
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, encounter);
    loop { wait(600); }
}
